package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"os"
	"sync/atomic"
	"time"

	"github.com/gopernicus/gopernicus/pockets/authorization"
	authorizationhttp "github.com/gopernicus/gopernicus/pockets/authorization/inbound/http"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/decisions"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/model"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/tuples"
	"github.com/gopernicus/gopernicus/pockets/authorization/stores/memory"
	"github.com/gopernicus/gopernicus/sdk"
)

func main() {
	if err := run(); err != nil { fmt.Fprintln(os.Stderr, err); os.Exit(1) }
}

func run() error {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	store := memory.NewTuples()
	err := store.ApplyTuples(ctx, tuples.Changes{Add: []tuples.Tuple{
		{Scope: tuples.Global(), Relation: "admin", Subject: tuples.SubjectRef{Type:"user", ID:"admin"}},
		{Scope: tuples.On("organization", "acme"), Relation: "member", Subject: tuples.SubjectRef{Type:"user", ID:"alice"}},
		{Scope: tuples.On("group", "editors"), Relation: "member", Subject: tuples.SubjectRef{Type:"user", ID:"alice"}},
		{Scope: tuples.On("document", "one"), Relation: "editor", Subject: tuples.SubjectRef{Type:"group", ID:"editors", Relation:"member"}},
	}})
	if err != nil { return err }
	policy := decisions.Model{ResourceTypes: map[string]decisions.ResourceTypeDef{
		"group": {Relations:map[string]decisions.RelationDef{"member":{AllowedSubjects:[]decisions.SubjectTypeRef{{Type:"user"}}}}},
		"document": {Relations:map[string]decisions.RelationDef{"editor":{AllowedSubjects:[]decisions.SubjectTypeRef{{Type:"user"},{Type:"group",Relation:"member"}}}}, Permissions:map[string]decisions.Expression{"edit":decisions.Direct("editor")}},
	}}
	components, err := authorization.New(authorization.Repositories{Tuples:store}, authorization.WithModel(policy))
	if err != nil { return err }
	document := authorizationhttp.Path("document", "documentID")
	guard := components.HTTP.Require(authorizationhttp.Any(
		authorizationhttp.HasRole("admin", authorizationhttp.Global()),
		authorizationhttp.All(
			authorizationhttp.HasRole("member", authorizationhttp.Fixed("organization", "acme")),
			authorizationhttp.HasRelationship("editor", document),
			authorizationhttp.Can("edit", document),
		),
	))
	var brokenReads atomic.Int64
	broken := authorizationhttp.Resource("document", func(*http.Request)(model.Resource,error){
		brokenReads.Add(1)
		return model.Resource{}, errors.New("fixture resolver failure")
	})
	lazy := components.HTTP.Require(authorizationhttp.Any(
		authorizationhttp.HasRole("admin", authorizationhttp.Global()),
		authorizationhttp.HasRole("owner", broken),
	))
	next := http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(http.StatusNoContent)})
	mux := http.NewServeMux()
	mux.Handle("GET /documents/{documentID}",guard(next))
	mux.Handle("GET /lazy",lazy(next))
	// This is fixture-only identity injection, bound exclusively to loopback.
	server := &http.Server{Handler:http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
		if user := r.Header.Get("X-Test-User"); user != "" { r = r.WithContext(sdk.WithPrincipal(r.Context(),sdk.Principal{Type:"user",ID:user})) }
		mux.ServeHTTP(w,r)
	}), ReadHeaderTimeout:time.Second}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil { return err }
	defer server.Close()
	go server.Serve(listener)
	transport := &http.Transport{Proxy:nil}
	defer transport.CloseIdleConnections()
	client := &http.Client{Timeout:2*time.Second, Transport:transport}
	type result struct { User, Path string; Status int }
	results := []result{}
	for _, tc := range []struct{user,path string; want int}{
		{"","/documents/one",401}, {"outsider","/documents/one",403},
		{"alice","/documents/one",204}, {"alice","/documents/two",403},
		{"admin","/documents/two",204}, {"admin","/lazy",204}, {"outsider","/lazy",500},
	} {
		req, err := http.NewRequestWithContext(ctx,http.MethodGet,"http://"+listener.Addr().String()+tc.path,nil)
		if err != nil { return err }
		req.Header.Set("X-Test-User",tc.user)
		response,err:=client.Do(req)
		if err!=nil{return err}
		response.Body.Close()
		if response.StatusCode!=tc.want{return fmt.Errorf("%s %s: got %d, want %d",tc.user,tc.path,response.StatusCode,tc.want)}
		if tc.user=="admin" && tc.path=="/lazy" && brokenReads.Load()!=0 {return errors.New("skipped resolver ran")}
		results=append(results,result{tc.user,tc.path,response.StatusCode})
	}
	if brokenReads.Load()!=1{return errors.New("resolver call count mismatch")}
	return json.NewEncoder(os.Stdout).Encode(struct{Passed bool; Requests []result; BrokenResolverCalls int64}{true,results,brokenReads.Load()})
}
